public class OperadoresAritmeticos {
    public static void main(String[] args) {
        int a = 15;
        int b = 4;

        System.out.println(a + " + " + b + " = " + (a + b));
        System.out.println(a + " - " + b + " = " + (a - b));
        System.out.println(a + " * " + b + " = " + (a * b));
        System.out.println(a + " / " + b + " = " + (a / b));
        System.out.println(a + " % " + b + " = " + (a % b));

        // Division con decimales
        double resultado = (double) a / b;
        System.out.println("Division exacta: " + resultado);

        // Ejercicio practico: es par o impar?
        int numero = 7;
        System.out.println("El numero " + numero + " es " +
            (numero % 2 == 0 ? "par" : "impar"));
    }
}

public class OperadoresRelacionales {
    public static void main(String[] args) {
        int edad = 20;
        double nota = 7.5;
        String nombre = "Ana";

        // Comparaciones numericas
        System.out.println("Edad >= 18: " + (edad >= 18));
        System.out.println("Nota > 5: " + (nota > 5));
        System.out.println("Edad == 20: " + (edad == 20));
        System.out.println("Edad != 25: " + (edad != 25));

        // Comparacion de cadenas (usando equals, no ==)
        System.out.println("Nombre es Ana: " + nombre.equals("Ana"));
    }
}

public class OperadoresLogicos {
    public static void main(String[] args) {
        int edad = 20;
        double nota = 7.5;
        boolean trabajador = false;

        // AND: ambas condiciones deben cumplirse
        boolean accesoCompleto = (edad >= 18) && (nota >= 5);
        System.out.println("Acceso completo: " + accesoCompleto);

        // OR: al menos una debe cumplirse
        boolean tieneBeneficio = (edad < 25) || trabajador;
        System.out.println("Tiene beneficio: " + tieneBeneficio);

        // NOT: invierte el valor
        boolean noTrabaja = !trabajador;
        System.out.println("No trabaja: " + noTrabaja);

        // Combinaciones complejas
        boolean puedeAcceder = (edad >= 18) && (nota >= 5) && !trabajador;
        System.out.println("Puede acceder: " + puedeAcceder);
    }
}

public class Precedencia {
    public static void main(String[] args) {
        int a = 5, b = 3, c = 2;

        // Sin parentesis: multiplicacion primero
        int resultado1 = a + b * c;  // 5 + 6 = 11
        System.out.println("a + b * c = " + resultado1);

        // Con parentesis: suma primero
        int resultado2 = (a + b) * c;  // 8 * 2 = 16
        System.out.println("(a + b) * c = " + resultado2);

        // Combinacion de operadores relacionales y logicos
        int edad = 25;
        double nota = 6.0;
        boolean apto = edad >= 18 && nota >= 5.0;
        System.out.println("Apto: " + apto);

        // Misma expresion con parentesis explicitos (mas legible)
        boolean aptoExplicito = (edad >= 18) && (nota >= 5.0);
        System.out.println("Apto (explicito): " + aptoExplicito);
    }
}

