/**
 * Clase que gestiona los datos de un estudiante.
 * 
 * <p>Esta clase almacena la informacion basica de un estudiante
 * y permite calcular su nota media.</p>
 * 
 * @author Profesor de Programacion
 * @version 1.0
 * @since 2026
 */
public class Estudiante {

    /** Nombre completo del estudiante */
    private String nombre;

    /** Edad del estudiante en anios */
    private int edad;

    /**
     * Constructor de la clase Estudiante.
     * 
     * @param nombre nombre completo del estudiante
     * @param edad edad del estudiante (debe ser mayor que 0)
     */
    public Estudiante(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
    }

    /**
     * Calcula la nota media de dos calificaciones.
     * 
     * @param nota1 primera calificacion (0.0 a 10.0)
     * @param nota2 segunda calificacion (0.0 a 10.0)
     * @return la nota media redondeada a dos decimales
     */
    public static double calcularMedia(double nota1, double nota2) {
        return (nota1 + nota2) / 2;
    }

    /**
     * Comprueba si el estudiante esta aprobado.
     * 
     * @param nota nota a comprobar
     * @return true si la nota es mayor o igual a 5.0
     */
    public static boolean estaAprobado(double nota) {
        return nota >= 5.0;
    }
}

