/**
 * Clase que ofrece metodos de calculo matematico basico.
 * 
 * @author Alumno de 1. DAM/DAW
 * @version 1.0
 */
public class CalculadoraBasica {

    /**
     * Calcula el area de un circulo a partir de su radio.
     * 
     * @param radio el radio del circulo (debe ser mayor que 0)
     * @return el area del circulo redondeada a 2 decimales
     */
    public static double calcularAreaCirculo(double radio) {
        return Math.PI * radio * radio;
    }

    public static void main(String[] args) {
        double radio = 5.0;
        double area = calcularAreaCirculo(radio);
        System.out.println("Area del circulo con radio " + radio + ": " + area);
    }
}

